\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme (Data-Report: Deep Navy + Teal + Cyan) ──
\definecolor{primary}{HTML}{0F2942}      % deep navy
\definecolor{secondary}{HTML}{0D7377}   % teal
\definecolor{accent}{HTML}{00B4D8}        % cyan/electric blue
\definecolor{bgposter}{HTML}{F0F7FA}       % cool light background
\definecolor{redbg}{HTML}{F0F9FF}         % light blue tint
\definecolor{bluebg}{HTML}{E8F6F6}        % teal tint
\definecolor{darkbg}{HTML}{E8EDF2}        % slate tint
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E0F4FF}
\definecolor{chinabg}{HTML}{FFF0E8}       % warm tint for China callout
\definecolor{indiabg}{HTML}{FFF8E8}       % warm tint for India callout

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darkbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.18},
  },
  bigstat/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stathighlight,
    borderline={2pt}{0pt}{accent},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    valign=center,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=35pt, right=35pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{88}\selectfont\bfseries Global Internet Usage}\\[8pt]
  {\fontsize{42}{52}\selectfont\bfseries A Cross-Country Comparison}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{white!80} Data Report 2025}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=stathighlight!50!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 5.56B}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global Internet Users}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} 68\% Penetration Rate}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary}{chinabg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 1.09B}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} China Online Pop.}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} 76\% Penetration}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary}{indiabg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 900M}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} India Online Pop.}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} 62\% Penetration}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ PENETRATION RATES (Center piece) ══
\posterbox[darkcard, title={Internet Penetration Rates by Country}]
{name=penetration, column=2, between=row7 and row14}{
  \fontsize{30}{38}\selectfont
  \rowcolors{1}{primary!8}{primary!4}
  \begin{tabular}{l r}
    \rowcolor{primary!15}
    \textbf{Country} & \textbf{Rate} \\[4pt]
    South Korea & 98\% \\
    United Kingdom & 97\% \\
    Germany & 96\% \\
    Japan & 95\% \\
    United States & 95\% \\
    Brazil & 88\% \\
    Indonesia & 78\% \\
    China & 76\% \\
    India & 62\% \\
    Nigeria & 52\% \\
  \end{tabular}
}

% ══ LEFT COLUMN: Digital Population ══
\posterbox[redcard, title={The World's Digital Population}]
{name=digitalpop, column=1, between=row7 and row11}{
  \fontsize{30}{40}\selectfont
  Asia dominates the global digital landscape with China and India accounting for over 35\% of all internet users worldwide.

  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont
    \textbf{Key Insight:} Top 10 countries by online population represent 4.2 billion users, or 76\% of global internet access.
  }}
}

% ══ LEFT COLUMN: Top Countries ══
\posterbox[redcard, title={Top Countries by Online Population}]
{name=topcountries, column=1, between=row11 and row15}{
  \fontsize{30}{38}\selectfont
  \rowcolors{1}{secondary!10}{secondary!5}
  \begin{tabular}{l r}
    \rowcolor{secondary!20}
    \textbf{Country} & \textbf{Online Pop.} \\[3pt]
    China & 1.09B \\
    India & 900M \\
    United States & 320M \\
    Indonesia & 220M \\
    Brazil & 190M \\
    Japan & 118M \\
    Nigeria & 115M \\
    Germany & 80M \\
  \end{tabular}
}

% ══ USAGE TRENDS (Right column) ══
\posterbox[bluecard, title={How People Spend Time Online}]
{name=usage, column=3, between=row7 and row12}{
  \fontsize{30}{38}\selectfont
  \textbf{Average Daily Social Media: 143 min}

  \vspace{6pt}
  \rowcolors{1}{accent!10}{accent!5}
  \begin{tabular}{l r}
    \rowcolor{accent!20}
    \textbf{Platform} & \textbf{Users} \\[3pt]
    Facebook & 3.1B \\
    YouTube & 2.5B \\
    WhatsApp & 2.4B \\
    Instagram & 2.0B \\
    TikTok & 1.6B \\
  \end{tabular}
  \vspace{6pt}
  Latin America and Southeast Asia lead in daily engagement time.
}

% ══ DIGITAL ECONOMY (Right column) ══
\posterbox[bluecard, title={The Digital Economy Impact}]
{name=economy, column=3, between=row12 and row15}{
  \fontsize{30}{38}\selectfont
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    {\fontsize{42}{52}\selectfont\bfseries\color{primary} \$8.0T}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark} E-Commerce Sales by 2027}
  }}

  \vspace{8pt}
  \fontsize{28}{36}\selectfont
  \begin{itemize}
    \item E-commerce: 20\%+ of total retail
    \item Mobile traffic: 60\%+ of web
    \item AI market: \$800B by 2030
  \end{itemize}
}

% ══ KEY TAKEAWAYS (Bottom) ══
\posterbox[highlightcard, title={Key Takeaways}]
{name=takeaways, column=1, span=3, between=row15 and row18}{
  \fontsize{32}{40}\selectfont
  \begin{tabular}{p{0.31\linewidth} p{0.31\linewidth} p{0.31\linewidth}}
    \rowcolor{primary!15}
    \centering\textbf{1. Regional Disparities} & \centering\textbf{2. Growth Engines} & \centering\textbf{3. Opportunity Gaps} \\[6pt]
    Asia leads in absolute numbers; Northern Europe leads in penetration rates. & Social media (143 min/day) and e-commerce driving digital economy expansion. & Sub-Saharan Africa and South Asia remain under-connected but represent growth potential. \\
  \end{tabular}
}

% ══ BOTTOM DATA POINTS ══
\posterbox[
  enhanced, colback=darkbg, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline north={2pt}{0pt}{primary!30},
]{name=bottomstats, column=1, span=3, between=row18 and bottom}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} 60\%+}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textdark} Mobile Web Traffic}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} 180ZB}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textdark} Global Data Created (2025)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} 3.1B}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textdark} Facebook Monthly Active}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} 2.5 hrs}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textdark} Avg. Daily Social Media}
  \end{minipage}
}

\end{tcbposter}
\end{document}

